function decodeAllAnimeSourceUrl(raw) {
  if (!raw || typeof raw !== "string") return "";
  let s = raw.trim();
  if (s.startsWith("--")) {
    const hex = s.slice(2);
    let out = "";
    for (let i = 0; i < hex.length; i += 2) {
      const pair = hex.substring(i, i + 2).toLowerCase();
      out += ALLANIME_HEX_MAP[pair] !== undefined ? ALLANIME_HEX_MAP[pair] : String.fromCharCode(parseInt(pair, 16) ^ 56);
    }
    s = out;
  }
  if (s.startsWith("/apivtwo/clock")) {
    s = "https://allanime.day" + s.replace("/clock?", "/clock.json?");
  } else if (/^https?:\/\/allanime\.day\/apivtwo\/clock(?!\.json)/i.test(s)) {
    s = s.replace("/clock?", "/clock.json?");
  }
  return s;
}

