function findDiskFile(names) {
  const candidates = Array.isArray(names) ? names : [names];
  const bases = [__dirname, process.cwd(), path.join(__dirname, "public"), path.join(process.cwd(), "public"), path.join(__dirname, "dist"), path.join(process.cwd(), "dist")];
  for (let i = 0; i < bases.length; i++) {
    for (let j = 0; j < candidates.length; j++) {
      const full = path.join(bases[i], candidates[j]);
      try {
        if (fs.existsSync(full) && fs.statSync(full).isFile()) return full;
      } catch (e) {}
    }
  }
  return null;
}

function sendJson(res, statusCode, obj) {
  res.writeHead(statusCode, {
    "Content-Type": "application/json; charset=utf-8",
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, HEAD, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Range"
  });
  res.end(JSON.stringify(obj));
}

function isSafeExternalStreamUrl(value) {
  try {
    const u = new URL(value);
    if (u.protocol !== "https:" && u.protocol !== "http:") return false;
    const h = u.hostname.toLowerCase();
    if (h === "localhost" || h === "127.0.0.1" || h === "0.0.0.0" || h.startsWith("169.254.") || h.startsWith("10.") || h.startsWith("192.168.")) return false;
    return true;
  } catch {
    return false;
  }
}

function proxyAssetUrl(value, baseUrl, referer) {
  const target = new URL(value, baseUrl).toString();
  const params = new URLSearchParams({ url: target, referer: referer || new URL(target).origin });
  return `/proxy?${params.toString()}`;
}

async function serveStreamProxy(req, res, parsedUrl) {
  const cors = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, HEAD, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Range",
    "Access-Control-Expose-Headers": "Accept-Ranges, Content-Length, Content-Range"
  };
  if (req.method === "OPTIONS") {
    res.writeHead(204, cors);
    return res.end();
  }

  const rawTarget = parsedUrl.searchParams.get("url") || "";
  if (!rawTarget || !isSafeExternalStreamUrl(rawTarget)) {
    return sendJson(res, 400, { error: "Invalid or missing stream url parameter" });
  }

  let target = new URL(rawTarget);
  let refererOrigin = target.origin;
  const rawRef = parsedUrl.searchParams.get("referer");
  if (rawRef) {
    try { refererOrigin = new URL(rawRef).origin; } catch {}
  }

  try {
    const requestHeaders = {
      "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
      "Referer": refererOrigin + "/",
      "Origin": refererOrigin,
      "Accept": "*/*"
    };
    if (req.headers.range) requestHeaders["Range"] = req.headers.range;

    let upstream = null;
    let current = target;
    for (let attempt = 0; attempt < 5; attempt++) {
      upstream = await fetch(current.href, { method: req.method === "HEAD" ? "HEAD" : "GET", headers: requestHeaders, redirect: "manual" });
      if (![301, 302, 303, 307, 308].includes(upstream.status)) break;
      const location = upstream.headers.get("location");
      if (!location) break;
      current = new URL(location, current);
      if (!isSafeExternalStreamUrl(current.href)) throw new Error("Unsafe redirect host");
    }
    if (!upstream) throw new Error("No response from upstream stream host");

    const contentType = upstream.headers.get("content-type") || "application/octet-stream";
    const isNamedPlaylist = /\.m3u8(?:$|\?)/i.test(current.href) || contentType.toLowerCase().includes("mpegurl");
    const isBinaryMedia = /\.(?:ts|m4s|mp4|webm|aac|mp3|vtt|jpg|jpeg|png|gif|woff2?)(?:$|\?)/i.test(current.href) || /^(?:video|audio|image|font)\//i.test(contentType);
    const contentLen = Number(upstream.headers.get("content-length") || 0);

    const responseHeaders = {
      ...cors,
      "Content-Type": isNamedPlaylist ? "application/vnd.apple.mpegurl" : contentType,
      "Accept-Ranges": upstream.headers.get("accept-ranges") || "bytes"
    };
    if (upstream.headers.get("content-length") && !isNamedPlaylist) {
      responseHeaders["Content-Length"] = upstream.headers.get("content-length");
    }
    if (upstream.headers.get("content-range")) {
      responseHeaders["Content-Range"] = upstream.headers.get("content-range");
    }

    if (req.method === "HEAD" || !upstream.body) {
      res.writeHead(upstream.status, responseHeaders);
      return res.end();
    }

    // Detect both standard .m3u8 playlists AND disguised #EXTM3U playlists (e.g., .txt or extensionless HLS manifests)
    if (upstream.ok && (isNamedPlaylist || (!isBinaryMedia && contentLen < 524288))) {
      const rawBuf = Buffer.from(await upstream.arrayBuffer());
      const headStr = rawBuf.subarray(0, 16).toString("utf8").trimStart();
      if (isNamedPlaylist || headStr.startsWith("#EXTM3U")) {
        const playlist = rawBuf.toString("utf8");
        const rewrite = (uri) => proxyAssetUrl(uri, current.href, refererOrigin);
        const rewritten = playlist
          .replace(/(URI=")([^"]+)(")/g, (_match, before, uri, after) => `${before}${rewrite(uri)}${after}`)
          .split(/\r?\n/)
          .map((line) => {
            const trimmed = line.trim();
            return trimmed && !trimmed.startsWith("#") ? rewrite(trimmed) : line;
          })
          .join("\n");
        delete responseHeaders["Content-Length"];
        responseHeaders["Content-Type"] = "application/vnd.apple.mpegurl";
        res.writeHead(200, responseHeaders);
        return res.end(rewritten);
      }
      res.writeHead(upstream.status, responseHeaders);
      return res.end(rawBuf);
    }

    res.writeHead(upstream.status, responseHeaders);
    if (upstream.body && typeof upstream.body.getReader === "function") {
      const streamBody = Readable.fromWeb(upstream.body);
      res.on("close", () => streamBody.destroy());
      streamBody.on("error", () => { if (!res.headersSent) res.writeHead(502, cors); res.end(); });
      return streamBody.pipe(res);
    }
    const buf = Buffer.from(await upstream.arrayBuffer());
    return res.end(buf);
  } catch (err) {
    if (!res.headersSent) {
      return sendJson(res, 502, { error: "Stream proxy failed: " + err.message });
    }
    res.end();
  }
}

async function handleRequest(req, res) {
  try {
    const host = req.headers.host || "localhost:" + PORT;
    const parsedUrl = new URL(req.url || "/", "http://" + host);
    let pathname = parsedUrl.pathname;

    if (req.method === "OPTIONS") {
      res.writeHead(204, {
        "Access-Control-Allow-Origin": "*",
        "Access-Control-Allow-Methods": "GET, POST, HEAD, OPTIONS",
        "Access-Control-Allow-Headers": "*"
      });
      return res.end();
    }

    if (pathname === "/healthz") {
      return sendJson(res, 200, { status: "ok", engine: "Anivexa 2.2.1" });
    }

    // PWA Icons, Manifest & Service Worker
    if (pathname === "/icon-192.png" || pathname === "/apple-touch-icon.png" || pathname === "/favicon.ico") {
      const diskPath = findDiskFile(["icon-192.png"]);
      const buf = diskPath ? fs.readFileSync(diskPath) : ICON_192_BUF;
      res.writeHead(200, { "Content-Type": "image/png", "Content-Length": buf.length, "Cache-Control": "public, max-age=86400" });
      return res.end(buf);
    }
    if (pathname === "/icon-512.png") {
      const diskPath = findDiskFile(["icon-512.png"]);
      const buf = diskPath ? fs.readFileSync(diskPath) : ICON_512_BUF;
      res.writeHead(200, { "Content-Type": "image/png", "Content-Length": buf.length, "Cache-Control": "public, max-age=86400" });
      return res.end(buf);
    }
    if (pathname === "/icon.svg" || pathname === "/anitag-mark.svg" || pathname === "/favicon.svg") {
      const iconPath = findDiskFile(["icon.svg", "anitag-mark.svg"]);
      const svgContent = iconPath ? fs.readFileSync(iconPath, "utf8") : INLINE_ICON_SVG;
      res.writeHead(200, { "Content-Type": "image/svg+xml; charset=utf-8", "Cache-Control": "public, max-age=86400" });
      return res.end(svgContent);
    }
    if (pathname === "/manifest.json" || pathname === "/manifest.webmanifest") {
      res.writeHead(200, { "Content-Type": "application/manifest+json; charset=utf-8", "Cache-Control": "no-cache" });
      return res.end(INLINE_MANIFEST);
    }
    if (pathname === "/sw.js") {
      res.writeHead(200, { "Content-Type": "application/javascript; charset=utf-8", "Service-Worker-Allowed": "/", "Cache-Control": "no-cache" });
      return res.end(INLINE_SW);
    }

    // Universal Stream Proxy (/proxy or /api/proxy)
    if (pathname === "/proxy" || pathname === "/api/proxy") {
      return await serveStreamProxy(req, res, parsedUrl);
    }

    // Strip optional /api prefix for Anivexa routes (/api/episodes/... -> /episodes/..., /api/watch/... -> /watch/..., /api/stream/2dhive/... -> /stream/2dhive/...)
    const strippedPathname = pathname === "/api/stream"
      ? pathname
      : pathname.replace(/^\/api(?=\/(?:episodes|watch|map|captcha)(?:\/|$)|\/stream\/)/, "");
    const isAnivexaRoute = (pathname !== "/api/stream") && (/^\/(?:episodes|watch|map|captcha)(?:\/|$)|^\/stream\//.test(strippedPathname) || pathname === "/api/info");

    if (isAnivexaRoute) {
      const workerUrl = new URL(parsedUrl.href);
      workerUrl.pathname = pathname === "/api/info" ? "/" : strippedPathname;
      const webReq = new Request(workerUrl.toString(), {
        method: req.method,
        headers: req.headers
      });
      const webRes = await anivexaWorker.fetch(webReq, {});
      res.statusCode = webRes.status;
      for (const [k, v] of webRes.headers) {
        res.setHeader(k, v);
      }
      res.setHeader("Access-Control-Allow-Origin", "*");
      const buf = Buffer.from(await webRes.arrayBuffer());
      return res.end(buf);
    }

    // Multi-provider fast stream resolver endpoint (/api/stream)
    // Combines Anivexa 2.2.1 (anikoto, animegg, anibd, 2dhive, mkissa, reanime, anizone, senshi, kaa) + AllAnime Clock Decryptor + Direct HLS Extractors
    if (pathname === "/api/stream") {
      const animeId = parsedUrl.searchParams.get("animeId") || "black-clover";
      const anilistId = parsedUrl.searchParams.get("anilistId") || "97940";
      const malId = parsedUrl.searchParams.get("malId") || "34572";
      const title = parsedUrl.searchParams.get("title") || "Black Clover";
      const ep = Number(parsedUrl.searchParams.get("ep") || "1");
      const audio = (parsedUrl.searchParams.get("audio") || "sub").toLowerCase() === "dub" ? "dub" : "sub";
      const preferredProvider = (parsedUrl.searchParams.get("provider") || "anikoto").toLowerCase();

      // Pre-seed Anivexa's media cache so providers skip the 3-4s Jikan/ARM lookup!
      if (typeof anivexaWorker.seedMedia === "function") {
        anivexaWorker.seedMedia(anilistId, malId, title);
      }

      const PROXY_REQUIRED_HOSTS = [
        "flixcloud.cc", "hianimes.re", "krussdomi.com", "vidmoly.biz", "vidmoly.net",
        "bysesayeveum.com", "upn.one", "allanime.day", "fast4speed.rsvp", "megacloud",
        "rapid-cloud", "biananset", "streambucket", "akamaized.net"
      ];

      function formatProviderStream(s, provName) {
        const rawTarget = s.extractedUrl || s.url || "";
        if (!rawTarget) return null;
        const sType = String(s.type || "").toLowerCase();
        const isEmbed = sType === "embed" || (sType === "iframe" && !s.extractedUrl);
        if (rawTarget.startsWith("/")) {
          return {
            ...s,
            server: s.server || s.name || provName.toUpperCase(),
            type: isEmbed ? "embed" : (s.type || "hls"),
            isM3U8: !isEmbed,
            rawUrl: rawTarget,
            url: rawTarget
          };
        }
        let hostName = "";
        let refOrigin = "";
        try {
          const uObj = new URL(rawTarget);
          hostName = uObj.hostname.toLowerCase();
          refOrigin = s.referer ? new URL(s.referer).origin : (s.headers && s.headers.Referer ? new URL(s.headers.Referer).origin : uObj.origin);
        } catch {
          return null;
        }
        const isHls = !isEmbed && (sType === "hls" || rawTarget.includes(".m3u8") || Boolean(s.isM3U8));
        const needsProxy = !isEmbed && (isHls || PROXY_REQUIRED_HOSTS.some((h) => hostName === h || hostName.endsWith("." + h) || hostName.includes(h)));
        const proxiedUrl = `/proxy?url=${encodeURIComponent(rawTarget)}&referer=${encodeURIComponent(refOrigin)}`;
        const finalUrl = needsProxy ? proxiedUrl : rawTarget;
        return {
          ...s,
          server: s.server || s.name || provName.toUpperCase(),
          type: isEmbed ? "embed" : (isHls ? "hls" : "mp4"),
          isM3U8: isHls,
          rawUrl: rawTarget,
          url: finalUrl,
          proxiedUrl
        };
      }

      async function tryAnivexaProvider(prov, timeoutMs = 7500) {
        const watchPath = `/watch/${prov}/${anilistId}/${audio}/${prov}-${ep}`;
        const wReq = new Request(`http://${host}${watchPath}`, { method: "GET" });
        const wRes = await Promise.race([
          anivexaWorker.fetch(wReq, {}),
          new Promise((_, rej) => setTimeout(() => rej(new Error("timeout")), timeoutMs))
        ]);
        if (!wRes || !wRes.ok) throw new Error("Provider status not ok");
        const data = await wRes.json();
        const rawStreams = Array.isArray(data.streams) ? data.streams : Array.isArray(data.sources) ? data.sources : [];
        const formatted = rawStreams.map((s) => formatProviderStream(s, prov)).filter(Boolean);
        const directOnly = formatted.filter((s) => String(s.type || "").toLowerCase() !== "embed");
        if (!directOnly.length) throw new Error("No direct video streams");
        return {
          provider: prov,
          streams: [...directOnly, ...formatted.filter((s) => String(s.type || "").toLowerCase() === "embed")],
          subtitles: data.subtitles || directOnly[0]?.subtitles || []
        };
      }

      async function tryAllAnimeDirect(timeoutMs = 6500) {
        const cleanTitle = String(title || "Black Clover").split(":")[0].split("Season")[0].trim();
        const searchGql = `query($search: SearchInput) { shows(search: $search, limit: 10, page: 1, translationType: ${audio}) { edges { _id name englishName nativeName aniListId availableEpisodesDetail } } }`;
        const ctrl = new AbortController();
        const timer = setTimeout(() => ctrl.abort(), timeoutMs);
        try {
          const sRes = await fetch("https://api.allanime.day/api", {
            method: "POST",
            signal: ctrl.signal,
            headers: {
              "Content-Type": "application/json",
              "Referer": "https://allanime.to/",
              "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
            },
            body: JSON.stringify({ query: searchGql, variables: { search: { query: cleanTitle, allowAdult: false, allowUnknown: false } } })
          });
          if (!sRes.ok) throw new Error("allanime search failed");
          const sJson = await sRes.json();
          const edges = (sJson && sJson.data && sJson.data.shows && sJson.data.shows.edges) || [];
          if (!edges.length) throw new Error("no edges");

          // Pick exact aniListId match or show that actually has episode `ep` in availableEpisodesDetail[audio]
          let chosenShow = edges.find((e) => e.aniListId && String(e.aniListId) === String(anilistId));
          if (!chosenShow) {
            chosenShow = edges.find((e) => {
              const epArr = e.availableEpisodesDetail && e.availableEpisodesDetail[audio];
              return Array.isArray(epArr) && epArr.map(String).includes(String(ep));
            });
          }
          if (!chosenShow) chosenShow = edges[0];

          const epGql = `query($showId: String!, $translationType: VaildTranslationTypeEnumType!, $episodeString: String!) { episode(showId: $showId, translationType: $translationType, episodeString: $episodeString) { sourceUrls } }`;
          const epRes = await fetch("https://api.allanime.day/api", {
            method: "POST",
            signal: ctrl.signal,
            headers: {
              "Content-Type": "application/json",
              "Referer": "https://allanime.to/",
              "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
            },
            body: JSON.stringify({ query: epGql, variables: { showId: chosenShow._id, translationType: audio, episodeString: String(ep) } })
          });
          if (!epRes.ok) throw new Error("allanime ep failed");
          const epJson = await epRes.json();
          const sourceUrls = (epJson && epJson.data && epJson.data.episode && epJson.data.episode.sourceUrls) || [];
          const out = [];

          await Promise.all(sourceUrls.slice(0, 6).map(async (srcObj) => {
            const decoded = decodeAllAnimeSourceUrl(srcObj.sourceUrl || "");
            if (!decoded) return;
            const sName = srcObj.sourceName || "AllAnime HD";

            // Resolve /apivtwo/clock.json endpoints on allanime.day
            if (decoded.includes("allanime.day/apivtwo/clock.json")) {
              try {
                const cRes = await fetch(decoded, {
                  signal: ctrl.signal,
                  headers: {
                    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
                    "Referer": "https://allanime.day/player.html",
                    "Accept": "*/*"
                  }
                });
                if (cRes.ok) {
                  const cJson = await cRes.json();
                  const links = Array.isArray(cJson.links) ? cJson.links : [];
                  links.forEach((lk) => {
                    if (lk && lk.link && lk.link.startsWith("http")) {
                      const isHls = Boolean(lk.hls || lk.link.includes(".m3u8"));
                      const formatted = formatProviderStream({
                        server: `${sName} Direct`,
                        type: isHls ? "hls" : "mp4",
                        isM3U8: isHls,
                        url: lk.link,
                        referer: "https://allanime.day/"
                      }, "allanime");
                      if (formatted) out.push(formatted);
                    }
                  });
                }
              } catch {}
            } else if (decoded.startsWith("https://") && (decoded.includes(".mp4") || decoded.includes(".m3u8") || decoded.includes("fast4speed") || decoded.includes("wixmp") || decoded.includes("sharepoint") || decoded.includes("akamaized"))) {
              const isHls = decoded.includes(".m3u8");
              const formatted = formatProviderStream({
                server: `${sName} Direct`,
                type: isHls ? "hls" : "mp4",
                isM3U8: isHls,
                url: decoded,
                referer: "https://allanime.day/"
              }, "allanime");
              if (formatted) out.push(formatted);
            }
          }));

          if (!out.length) throw new Error("no decoded urls");
          return { provider: "allanime", streams: out, subtitles: [] };
        } finally {
          clearTimeout(timer);
        }
      }

      async function tryDirectHlsExtractors(timeoutMs = 6000) {
        const ctrl = new AbortController();
        const timer = setTimeout(() => ctrl.abort(), timeoutMs);
        try {
          const results = [];
          await Promise.allSettled([
            // 1. 2dhive HiAnime API
            (async () => {
              const r = await fetch(`https://2dhive.com/api/hianime?mal_id=${malId}&ep_num=${ep}&dub=${audio === "dub" ? 1 : 0}`, {
                signal: ctrl.signal,
                headers: { "User-Agent": "Mozilla/5.0", "Referer": "https://2dhive.com/" }
              });
              if (r.ok) {
                const j = await r.json();
                if (j && j.m3u8) {
                  const f = formatProviderStream({
                    server: "HiAnime Direct HLS",
                    type: "hls",
                    isM3U8: true,
                    url: j.m3u8,
                    referer: "https://2dhive.com/",
                    subtitles: j.subtitle ? [{ url: j.subtitle, label: "English", srclang: "en", default: true }] : []
                  }, "2dhive");
                  if (f) results.push(f);
                }
              }
            })(),
            // 2. BabaStream CFG direct m3u8 extraction
            (async () => {
              const bUrl = `https://babastream.top/embed/${malId}/${ep}/${audio}`;
              const r = await fetch(bUrl, {
                signal: ctrl.signal,
                headers: { "User-Agent": "Mozilla/5.0", "Referer": "https://2dhive.com/" }
              });
              if (r.ok) {
                const txt = await r.text();
                const m = txt.match(/\bvar\s+CFG\s*=\s*(\{[^;]+\})\s*;/);
                if (m) {
                  const cfg = JSON.parse(m[1]);
                  if (cfg.primary && cfg.mal && cfg.ep && cfg.sub) {
                    const hlsUrl = `${cfg.primary.replace(/\/+$/, "")}/v2/${encodeURIComponent(cfg.mal)}/${encodeURIComponent(cfg.ep)}/${encodeURIComponent(cfg.sub)}/.m3u8?v=3`;
                    const f = formatProviderStream({
                      server: "BabaStream Direct HLS",
                      type: "hls",
                      isM3U8: true,
                      url: hlsUrl,
                      referer: "https://babastream.top/"
                    }, "babastream");
                    if (f) results.push(f);
                  }
                }
              }
            })()
          ]);
          if (!results.length) throw new Error("No direct extractors succeeded");
          return { provider: "direct-hls", streams: results, subtitles: results[0]?.subtitles || [] };
        } finally {
          clearTimeout(timer);
        }
      }

      // Race preferred provider + fast backup providers + AllAnime Direct + Direct HLS Extractors concurrently
      const candidates = [preferredProvider, "anikoto", "animegg", "anibd", "2dhive", "reanime", "anizone", "senshi", "kaa", "mkissa"]
        .filter((v, idx, arr) => v && arr.indexOf(v) === idx)
        .slice(0, 6);

      try {
        const winner = await Promise.any([
          ...candidates.map((p) => tryAnivexaProvider(p, 7500)),
          tryAllAnimeDirect(6500),
          tryDirectHlsExtractors(6000)
        ]);
        if (winner && winner.streams && winner.streams.length) {
          const primary = winner.streams[0];
          return sendJson(res, 200, {
            status: "ok",
            provider: winner.provider,
            anilistId: Number(anilistId),
            malId: Number(malId),
            episode: ep,
            audio,
            isM3U8: Boolean(primary.isM3U8),
            type: primary.type || "hls",
            url: primary.url,
            rawUrl: primary.rawUrl || primary.url,
            streams: winner.streams,
            subtitles: winner.subtitles || primary.subtitles || []
          });
        }
      } catch (e) {}

      // Clean Full-Episode Fallback (Zero 90-second opening clips!)
      const upperAudio = audio.toUpperCase();
      const verifiedFullEpisodeStreams = [
        {
          server: `MegaPlay HD (${upperAudio})`,
          type: "embed",
          isM3U8: false,
          url: `https://megaplay.buzz/stream/mal/${malId}/${ep}/${audio}`,
          rawUrl: `https://megaplay.buzz/stream/mal/${malId}/${ep}/${audio}`
        },
        {
          server: `VidSrc CC HD (${upperAudio})`,
          type: "embed",
          isM3U8: false,
          url: `https://vidsrc.cc/v2/embed/anime/ani${anilistId}/${ep}/${audio}?autoPlay=true`,
          rawUrl: `https://vidsrc.cc/v2/embed/anime/ani${anilistId}/${ep}/${audio}?autoPlay=true`
        },
        {
          server: `VidLink Cloud HD (${upperAudio})`,
          type: "embed",
          isM3U8: false,
          url: `https://vidlink.pro/anime/${malId}/${ep}/${audio}?fallback=true&autoplay=true&primaryColor=E8C36A`,
          rawUrl: `https://vidlink.pro/anime/${malId}/${ep}/${audio}?fallback=true&autoplay=true&primaryColor=E8C36A`
        }
      ];

      return sendJson(res, 200, {
        status: "ok",
        provider: preferredProvider,
        anilistId: Number(anilistId),
        malId: Number(malId),
        episode: ep,
        audio,
        isM3U8: false,
        type: "embed",
        url: verifiedFullEpisodeStreams[0].url,
        rawUrl: verifiedFullEpisodeStreams[0].rawUrl,
        streams: verifiedFullEpisodeStreams,
        subtitles: []
      });
    }

    // Serve Frontend HTML
    const htmlPath = findDiskFile(["index.html", "anikage_app.html"]);
    if (htmlPath) {
      const htmlContent = fs.readFileSync(htmlPath, "utf8");
      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
      return res.end(htmlContent);
    }

    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
    return res.end("<!DOCTYPE html><html><body style=\"background:#0b0b0e;color:#fff;font-family:sans-serif;padding:2rem;\"><h1>AniTAG Server Running</h1></body></html>");
  } catch (err) {
    return sendJson(res, 500, { status: "error", message: err.message });
  }
}

if (require.main === module) {
  const server = http.createServer(handleRequest);
  server.listen(PORT, () => {
    console.log("AniTAG + Anivexa 2.2.1 Server listening on port " + PORT);
  });
}

module.exports = handleRequest;
